    21	            from LoanJpaEntity l, BookJpaEntity b
    22	            where b.id = l.bookId and l.memberId = :memberId and l.returnedAt is null
    23	            order by l.loanedAt asc, l.id asc
    24	            """,
    25	            countQuery = """
    26	            select count(l) from LoanJpaEntity l
    27	            where l.memberId = :memberId and l.returnedAt is null
    28	            """)
