     1	package com.example.lending.domain;
     2	
     3	import java.time.LocalDate;
     4	import java.time.temporal.ChronoUnit;
     5	import java.util.Objects;
     6	import java.util.UUID;
     7	
     8	public class Loan {
     9	
    10	    static final int LOAN_PERIOD_DAYS = 14;
    11	    static final long LATE_FEE_PER_DAY = 100;
    12	
    13	    private final UUID id;
    14	    private final UUID bookId;
    15	    private final UUID memberId;
    16	    private final LocalDate loanedAt;
    17	    private final LocalDate dueAt;
    18	    private LocalDate returnedAt;
    19	    // 신용조회를 거치지 않은 대출은 null 이다
    20	    private final CreditCheck creditCheck;
    21	
    22	    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
    23	                 CreditCheck creditCheck) {
    24	        this.id = Objects.requireNonNull(id, "id");
    25	        this.bookId = Objects.requireNonNull(bookId, "bookId");
    26	        this.memberId = Objects.requireNonNull(memberId, "memberId");
    27	        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
    28	        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
    29	        if (dueAt.isBefore(loanedAt)) {
    30	            throw new IllegalArgumentException("dueAt must not be before loanedAt");
    31	        }
    32	        this.returnedAt = returnedAt;
    33	        this.creditCheck = creditCheck;
    34	    }
    35	
    36	    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    37	    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt, CreditCheck creditCheck) {
    38	        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null,
    39	                Objects.requireNonNull(creditCheck, "creditCheck"));
    40	    }
    41	
    42	    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
    43	                                    LocalDate returnedAt, CreditCheck creditCheck) {
    44	        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    45	    }
    46	
    47	    public void markReturned(LocalDate returnedAt) {
    48	        if (isReturned()) {
    49	            throw new LoanAlreadyReturnedException(id);
    50	        }
    51	        Objects.requireNonNull(returnedAt, "returnedAt");
    52	        if (returnedAt.isBefore(loanedAt)) {
    53	            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
    54	        }
    55	        this.returnedAt = returnedAt;
    56	    }
    57	
    58	    public boolean isReturned() {
    59	        return returnedAt != null;
    60	    }
    61	
    62	    public boolean isOverdue(LocalDate today) {
    63	        return today.isAfter(dueAt);
    64	    }
    65	
    66	    // 기한 당일 반납은 연체가 아니다. 반납 전이면 연체일은 0이다.
    67	    public long overdueDays() {
    68	        if (!isReturned() || !returnedAt.isAfter(dueAt)) {
    69	            return 0;
    70	        }
    71	        return ChronoUnit.DAYS.between(dueAt, returnedAt);
