    public MemberLoanPageResponse getMemberLoans(@PathVariable UUID memberId,
                                                 @RequestParam(defaultValue = "0") int page,
                                                 @RequestParam(defaultValue = "20") int size) {
        return MemberLoanPageResponse.from(
                getMemberLoansUseCase.getActiveLoans(new GetMemberLoansQuery(memberId, page, size)));
    }

    // 반납된 대출을 포함한 전체 이력을 대출일 최신순으로 조회한다
    @GetMapping("/{memberId}/loans/history")
    public List<MemberLoanHistoryResponse> getMemberLoanHistory(@PathVariable UUID memberId) {
        return getMemberLoanHistoryUseCase.getLoanHistory(memberId).stream()
                .map(MemberLoanHistoryResponse::from)
                .toList();
    }
}

